    results.append({'variant':variant,'compile_exit':0,'test_exit':r.returncode,'manifest_sha256':digest((target/'manifest.json').read_bytes()),'test_jar_sha256':digest((target/'tests.jar').read_bytes()),'test_log_sha256':digest((target/'junit.log').read_bytes())})
(OUT/'results.json').write_text(json.dumps(results,indent=2)+'\n')
sys.exit(results[-1]['test_exit'])

package dev.chungjungsoo.gptmobile.data.voice
import java.io.File
import java.util.concurrent.ConcurrentLinkedQueue
import java.util.concurrent.atomic.AtomicInteger

// Explicit host boundaries. The retirement, loading, warmup and cancellation methods are extracted unchanged.
internal interface VoicePhraseEngine {
    fun resetCancellation() = Unit
    fun cancel() = Unit
    fun close()
}
internal interface VoiceFailoverPhraseEngine : VoicePhraseEngine { val canReuse: Boolean }
internal interface VoicePhraseEngineFactory {
    val identity: String
    val residentIdentity: String get() = identity
    val selectedBackend: VoiceSpeechBackend
    val requiresKokoroAssets: Boolean get() = false
    val nativeCleanupPending: Boolean get() = false
    fun isReady() = true
    fun cancelPending() = Unit
    fun prepareForPlayback(engine: VoicePhraseEngine) = Unit
    fun prefetchAssets(current: () -> Boolean) = Unit
    fun preloadRuntime() = Unit
    fun create(directory: File, lexicon: String, threads: Int): VoicePhraseEngine
}
internal class LeasePort {
    val leases = AtomicInteger()
    fun isInstalled() = true
    fun acquireUse(): Boolean { leases.incrementAndGet(); return true }
    fun releaseUse() { check(leases.decrementAndGet() >= 0) }
    fun modelDirectory() = File(".")
}
internal class MainQueuePort {
    private val queue = ConcurrentLinkedQueue<() -> Unit>()
    fun post(task: () -> Unit) { queue.add(task) }
    fun idle() { while (true) (queue.poll() ?: return).invoke() }
}
internal object Looper {
    lateinit var owner: MainQueuePort
    fun getMainLooper() = owner
}
internal fun shadowOf(queue: MainQueuePort) = queue
internal object AppLogRecorder { fun record(tag: String, message: String, level: String = "I") = Unit }
internal object SystemClock { fun elapsedRealtime() = System.nanoTime() / 1_000_000 }
internal class ConversationPrivacyContext {
    companion object { fun <T> withCaptured(context: ConversationPrivacyContext?, block: () -> T): T = block() }
}
internal object VoiceCpuCalibrationProtocol { fun rate(value: Float) = value }

package dev.chungjungsoo.gptmobile.data.voice
import java.io.File
import java.util.concurrent.CountDownLatch
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicInteger
import org.junit.Test
import org.junit.Assert.*

class KokoroRetirementEpochTest {
    private fun withStreamingOutput(
        incremental: Boolean,
        pause: VoicePauseDuration,
        engine: VoicePhraseEngine,
        beforeCreate: () -> Unit = {},
        block: (KokoroVoiceOutput) -> Unit
    ) {
        val factory = object : VoicePhraseEngineFactory {
            override val identity = "host-retirement-fixture"
            override val selectedBackend = VoiceSpeechBackend.PHONON_CPU
            override fun create(directory: File, lexicon: String, threads: Int): VoicePhraseEngine { beforeCreate(); return engine }
        }
        val output = KokoroVoiceOutput(factory)
        try { block(output) } finally { output.disposeFixture() }
    }
    private fun awaitMain(latch: CountDownLatch) {
        val end = System.nanoTime() + TimeUnit.SECONDS.toNanos(1)
        while (latch.count != 0L && System.nanoTime() < end) {
            Looper.getMainLooper().idle()
            latch.await(2, TimeUnit.MILLISECONDS)
        }
        Looper.getMainLooper().idle()
    }

    @Test fun actualReleaseModelKeepsAssetLeaseAfterNativeCloseFailureAndRejectsNewLoad() {
        val creations = AtomicInteger()
        val factory = object : VoicePhraseEngineFactory {
            override val identity = "close-failure"
            override val selectedBackend = VoiceSpeechBackend.PHONON_CPU
            override val requiresKokoroAssets = true
            override fun create(directory: File, lexicon: String, threads: Int): VoicePhraseEngine {
                creations.incrementAndGet()
                return object : VoicePhraseEngine { override fun close() { error("native close fixture failure") } }
            }
        }
        val output = KokoroVoiceOutput(factory)
        val acknowledged = AtomicBoolean()
        try {
            output.prewarm(KokoroVoice.HEART)
            output.awaitSynthesis()
            assertEquals(1, output.models.leases.get())
            output.releaseWarmModel { acknowledged.set(true) }
            output.awaitWorkers()
            assertFalse(acknowledged.get())
            assertEquals(1, output.models.leases.get())
            output.prewarm(KokoroVoice.HEART)
            output.awaitWorkers()
            assertEquals(1, creations.get())
            assertEquals(1, output.models.leases.get())
        } finally { output.disposeFixture() }
    }

    @Test fun actualPreparationQuarantineRetainsLeaseAndRejectsReplacement() {
        val creations = AtomicInteger()
        val factory = object : VoicePhraseEngineFactory {
            override val identity = "partial-open-failure"
            override val selectedBackend = VoiceSpeechBackend.PHONON_CPU
            override val requiresKokoroAssets = true
            override val nativeCleanupPending get() = creations.get() > 0
            override fun create(directory: File, lexicon: String, threads: Int): VoicePhraseEngine {
                creations.incrementAndGet()
                error("native partial-open fixture failure")
            }
        }
        val output = KokoroVoiceOutput(factory)
        val acknowledged = AtomicBoolean()
        try {
            output.prewarm(KokoroVoice.HEART)
            output.awaitWorkers()
            assertEquals(1, output.models.leases.get())
            output.releaseWarmModel { acknowledged.set(true) }
            output.awaitWorkers()
            assertFalse(acknowledged.get())
            output.prewarm(KokoroVoice.HEART)
            output.awaitWorkers()
            assertEquals(1, creations.get())
            assertEquals(1, output.models.leases.get())
        } finally { output.disposeFixture() }
    }

    @Test fun successfulModelRetirementStillWaitsForPlaybackWorkerExit() {
        val entered = CountDownLatch(1)
        val allowExit = CountDownLatch(1)
        val retired = AtomicBoolean()
        val acknowledged = CountDownLatch(1)
        val engine = object : VoicePhraseEngine { override fun close() { retired.set(true) } }
        withStreamingOutput(false, VoicePauseDuration.NATURAL, engine) { output ->
            output.prewarm(KokoroVoice.HEART)
            output.awaitSynthesis()
            output.queuePlayback { entered.countDown(); check(allowExit.await(3, TimeUnit.SECONDS)) }
            assertTrue(entered.await(3, TimeUnit.SECONDS))
            try {
                output.releaseWarmModel { acknowledged.countDown() }
                output.awaitSynthesis()
                Looper.getMainLooper().idle()
                assertTrue(retired.get())
                assertEquals(1L, acknowledged.count)
            } finally { allowExit.countDown() }
            awaitMain(acknowledged)
            assertEquals(0L, acknowledged.count)
        }
    }
    @Test fun confirmedWarmReleaseSurvivesRepeatedStopWhileNativeCloseIsPending() {
        assertConfirmedReleaseAcrossCancellation { output ->
            output.stop("speech_benchmark_running")
            output.stop("session_paused")
        }
    }

    @Test fun confirmedWarmReleaseSurvivesCancelPrewarmWhileNativeCloseIsPending() {
        assertConfirmedReleaseAcrossCancellation { output ->
            output.cancelPrewarm()
            output.cancelPrewarm()
        }
    }

    @Test fun heldSessionAccessRefreshCannotInvalidateConfirmedOutputRetirement() {
        var session: VoiceSession? = null
        try {
            assertConfirmedReleaseAcrossCancellation { output ->
                val system = object : VoiceAudio {
                    override fun listen(listener: VoiceAudio.Listener) = error("No microphone is admitted")
                    override fun speak(text: String, complete: () -> Unit, error: (String) -> Unit) = Unit
                    override fun stop() = Unit
                    override fun close() = Unit
                }
                val local = object : VoiceRecognitionInput {
                    override var languageTag = "en-US"
                    override fun listen(listener: VoiceAudio.Listener) = error("No microphone is admitted")
                    override fun stop() = Unit
                    override fun close() = Unit
                }
                val audio = VoicePluginAudio(system, local, output, releaseSystemRecognition = {})
                val owner = VoiceSession(audio, { true }, {})
                session = owner
                owner.access(true, true, true)
                owner.holdAudio(true)
                // The real screen repeats this access update when benchmarkRunning changes.
                owner.access(true, true, true)
                assertEquals(VoicePhase.PAUSED, owner.state.phase)
            }
        } finally {
            session?.close()
        }
    }

    @Test fun factoryReplacementInvalidatesAPendingReleaseAcknowledgement() {
        val created = CountDownLatch(1)
        val closing = CountDownLatch(1)
        val allowClose = CountDownLatch(1)
        val acknowledged = AtomicBoolean()
        val engine = object : VoicePhraseEngine {
            override fun resetCancellation() = Unit
            override fun cancel() = Unit
            override fun close() {
                closing.countDown()
                check(allowClose.await(5, TimeUnit.SECONDS))
            }
        }
        withStreamingOutput(false, VoicePauseDuration.NATURAL, engine, beforeCreate = { created.countDown() }) { output ->
            try {
                output.prewarm(KokoroVoice.HEART)
                assertTrue(created.await(3, TimeUnit.SECONDS))
                output.releaseWarmModel { acknowledged.set(true) }
                assertTrue(closing.await(3, TimeUnit.SECONDS))
                output.configureEngine(object : VoicePhraseEngineFactory {
                    override val identity = "retirement-replacement-test"
                    override val requiresKokoroAssets = false
                    override val selectedBackend = VoiceSpeechBackend.PHONON_CPU
                    override fun create(directory: File, lexicon: String, threads: Int): VoicePhraseEngine =
                        error("Replacement configuration must not load the model")
                })
            } finally {
                allowClose.countDown()
            }
            val replacementRelease = CountDownLatch(1)
            output.releaseWarmModel { replacementRelease.countDown() }
            awaitMain(replacementRelease)
            assertEquals(0L, replacementRelease.count)
            assertFalse(acknowledged.get())
        }
    }

    @Test fun interveningWarmupInvalidatesAPendingReleaseAcknowledgement() {
        val firstCreated = CountDownLatch(1)
        val replacementCreated = CountDownLatch(1)
        val closing = CountDownLatch(1)
        val allowClose = CountDownLatch(1)
        val constructions = AtomicInteger()
        val acknowledged = AtomicBoolean()
        val engine = object : VoicePhraseEngine {
            override fun resetCancellation() = Unit
            override fun cancel() = Unit
            override fun close() {
                closing.countDown()
                check(allowClose.await(5, TimeUnit.SECONDS))
            }
        }
        withStreamingOutput(false, VoicePauseDuration.NATURAL, engine, beforeCreate = {
            if (constructions.incrementAndGet() == 1) firstCreated.countDown() else replacementCreated.countDown()
        }) { output ->
            try {
                output.prewarm(KokoroVoice.HEART)
                assertTrue(firstCreated.await(3, TimeUnit.SECONDS))
                output.releaseWarmModel { acknowledged.set(true) }
                assertTrue(closing.await(3, TimeUnit.SECONDS))
                output.prewarm(KokoroVoice.HEART)
            } finally {
                allowClose.countDown()
            }
            assertTrue(replacementCreated.await(3, TimeUnit.SECONDS))
            val finalRelease = CountDownLatch(1)
            output.releaseWarmModel { finalRelease.countDown() }
            awaitMain(finalRelease)
            assertEquals(0L, finalRelease.count)
            assertFalse(acknowledged.get())
        }
    }

    private fun assertConfirmedReleaseAcrossCancellation(cancel: (KokoroVoiceOutput) -> Unit) {
        val created = CountDownLatch(1)
        val closing = CountDownLatch(1)
        val allowClose = CountDownLatch(1)
        val retired = AtomicBoolean()
        val acknowledged = CountDownLatch(1)
        val completions = AtomicInteger()
        val engine = object : VoicePhraseEngine {
            override fun resetCancellation() = Unit
            override fun cancel() = Unit
            override fun close() {
                closing.countDown()
                check(allowClose.await(5, TimeUnit.SECONDS))
                retired.set(true)
            }
        }
        withStreamingOutput(false, VoicePauseDuration.NATURAL, engine, beforeCreate = { created.countDown() }) { output ->
            try {
                output.prewarm(KokoroVoice.HEART)
                assertTrue(created.await(3, TimeUnit.SECONDS))
                output.releaseWarmModel {
                    assertTrue(retired.get())
                    completions.incrementAndGet()
                    acknowledged.countDown()
                }
                assertTrue(closing.await(3, TimeUnit.SECONDS))
                cancel(output)
                shadowOf(Looper.getMainLooper()).idle()
                assertEquals(1L, acknowledged.count)
                assertEquals(0, completions.get())
            } finally {
                allowClose.countDown()
            }
            awaitMain(acknowledged)
            assertEquals(0L, acknowledged.count)
            assertEquals(1, completions.get())
            val secondRelease = CountDownLatch(1)
            output.releaseWarmModel { secondRelease.countDown() }
            awaitMain(secondRelease)
            assertEquals(0L, secondRelease.count)
            assertEquals(1, completions.get())
        }
    }
}
